def transform(grid):
    # Count separate non-background horizontal objects by their color, then
    # encode those objects as cells in a three-column grid, grouped by color.
    h, w = len(grid), len(grid[0])
    counts = {3: 0, 2: 0}
    for r in range(h):
        c = 0
        while c < w:
            color = grid[r][c]
            if color in counts:
                counts[color] += 1
                while c < w and grid[r][c] == color:
                    c += 1
            else:
                c += 1
    cells = [3] * counts[3] + [2] * counts[2]
    width = 3
    rows = (len(cells) + width - 1) // width
    cells += [0] * (rows * width - len(cells))
    return [cells[i:i + width] for i in range(0, len(cells), width)]
